import { strictNumber } from '../';

describe('strictNumber mask', () => {
  it('should not mask null', () => {
    expect(strictNumber(null)).toEqual(null);
  });

  it('should not mask numbers', () => {
    expect(strictNumber('53.27')).toEqual('53.27');
  });

  it('should parse out the first available piece', () => {
    expect(strictNumber('5aa3.2aa7')).toEqual('5');
    expect(strictNumber('aa3.2aa7aa5')).toEqual('3.2');
  });

  it('should mask letters', () => {
    expect(strictNumber('aa9.3bb')).toEqual('9.3');
  });

  it('should allow negative', () => {
    expect(strictNumber('-53.27')).toEqual('-53.27');
  });

  it('should not allow negative signs in the middle', () => {
    expect(strictNumber('-5-3.27')).toEqual('-5');
  });

  it('should not allow decimals in the middle', () => {
    expect(strictNumber('-5.3.27')).toEqual('-5.3');
  });
});
